def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def = opp.count('D')
    my_def = me.count('D')

    if opp_def == 0:
        if n >= 96:
            return 'D'
        return 'C' if n % 23 != 0 else 'D'
    if opp_def == n:
        return 'D'

    if n == 1:
        return 'C'
    if n == 2:
        return 'D' if opp[-1] == 'D' else 'C'

    recent_opp = opp[-5:] if n >= 5 else opp
    recent_me = me[-5:] if n >= 5 else me
    opp_recent_def = recent_opp.count('D')
    my_recent_def = recent_me.count('D')

    if opp_recent_def == 0:
        if n >= 92:
            return 'D'
        if n % 19 == 0 and n > 12:
            return 'D'
        return 'C'

    if opp_recent_def >= 4:
        return 'D'

    if n >= 90:
        if opp_recent_def <= 1:
            return 'D'
        if opp[-1] == 'D':
            return 'D'
        return 'C' if rng.random() < 0.5 else 'D'

    opp_after_c = 0
    opp_after_c_d = 0
    opp_after_d = 0
    opp_after_d_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            opp_after_c += 1
            if opp[i + 1] == 'D':
                opp_after_c_d += 1
        else:
            opp_after_d += 1
            if opp[i + 1] == 'D':
                opp_after_d_d += 1
    p_d_after_c = opp_after_c_d / opp_after_c if opp_after_c else 0.0
    p_d_after_d = opp_after_d_d / opp_after_d if opp_after_d else 0.0

    if opp_after_d >= 3 and p_d_after_d > p_d_after_c + 0.25:
        return 'C'

    if n > 20 and opp_after_c >= 5 and p_d_after_c > p_d_after_d + 0.3:
        if opp[-1] == 'C' and opp_recent_def <= 2:
            return 'D'

    if opp[-1] == 'D':
        if opp_recent_def >= 2:
            return 'D'
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    if n > 10 and opp_recent_def <= 1 and my_recent_def <= 2:
        if rng.random() < 0.1:
            return 'D'
    return 'C'
